CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL DEFAULT 'local-user', original_name text NOT NULL, mime_type text NOT NULL, storage_path text NOT NULL, status text NOT NULL DEFAULT 'uploaded', risk_flags jsonb NOT NULL DEFAULT '[]', uploaded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE source_chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), file_id uuid NOT NULL REFERENCES files(id), sequence text NOT NULL, page_number text, section_title text, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE experiences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL DEFAULT 'local-user', type text NOT NULL, organization_name text, title text NOT NULL, team_name text, start_date text, end_date text, summary text, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evidence_points (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), experience_id uuid NOT NULL REFERENCES experiences(id), category text NOT NULL, content text NOT NULL, skills jsonb NOT NULL DEFAULT '[]', tags jsonb NOT NULL DEFAULT '[]', source_chunk_ids jsonb NOT NULL DEFAULT '[]', confidence text NOT NULL, verification_status text NOT NULL DEFAULT 'source_backed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE merge_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), file_id uuid NOT NULL REFERENCES files(id), candidate_experience_id uuid REFERENCES experiences(id), decision_type text NOT NULL, reason text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
